import React from 'react';
import { Link } from 'react-router-dom';
import { useStore } from '../context/StoreContext';
import './ProductCard.css';

function formatPrice(price) {
  const value = Number(price || 0);
  return `$${value.toLocaleString('en-US', { maximumFractionDigits: 2 })}`;
}

function ProductCard({ product, compact = false }) {
  const { addToCart, toggleWishlist, isInWishlist } = useStore();

  if (!product) {
    return null;
  }

  const productId = product.id || product.productId || `dummyjson_${product.externalId}`;
  const image = product.image || product.thumbnail || product.images?.[0] || '';
  const rating = Number(product.rating || 0);
  const stock = Number(product.stock || 0);
  const isSaved = isInWishlist(productId);
  const discount = Number(product.discountPercentage || 0);

  const handleCartClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
    addToCart(product, 1);
  };

  const handleWishlistClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
    toggleWishlist(product);
  };

  return (
    <article className={compact ? 'product-card compact' : 'product-card'}>
      <Link to={`/products/${encodeURIComponent(productId)}`} className="product-card-link" aria-label={`View ${product.title}`}>
        <div className="product-image-wrap">
          <img
            src={image}
            alt={product.title || 'Tech product'}
            className="product-image"
            loading="lazy"
            onError={(event) => {
              event.currentTarget.src =
                'https://dummyjson.com/image/400x300/eeeeee/111111?text=Tech+Store';
            }}
          />

          <div className="product-card-badges">
            <span className="product-source">DummyJSON</span>
            {discount > 0 && <span className="product-discount">-{Math.round(discount)}%</span>}
          </div>

          <button
            type="button"
            className={isSaved ? 'wishlist-floating active' : 'wishlist-floating'}
            onClick={handleWishlistClick}
            aria-label={isSaved ? 'Remove from wishlist' : 'Add to wishlist'}
          >
            {isSaved ? '♥' : '♡'}
          </button>
        </div>

        <div className="product-card-body">
          <div className="product-meta-row">
            <span className="product-category">{product.category || 'Technology'}</span>
            <span className={stock > 0 ? 'stock-pill in-stock' : 'stock-pill out-stock'}>
              {stock > 0 ? 'In stock' : 'Out of stock'}
            </span>
          </div>

          <h3 className="product-title">{product.title || 'Tech Product'}</h3>

          <p className="product-description">
            {product.description || 'Explore this premium technology product with useful features and reliable performance.'}
          </p>

          <div className="product-rating-row">
            <span className="stars" aria-label={`Rating ${rating.toFixed(1)} out of 5`}>
              {'★'.repeat(Math.max(1, Math.round(rating))).slice(0, 5)}
              <span>{'☆'.repeat(Math.max(0, 5 - Math.round(rating))).slice(0, 5)}</span>
            </span>

            <strong>{rating ? rating.toFixed(1) : '4.5'}</strong>
            <small>({product.reviewCount || product.reviews?.length || 24})</small>
          </div>

          <div className="product-spec-chips">
            <span>{product.brand || 'Tech Brand'}</span>
            <span>{product.rawCategory || product.category || 'Device'}</span>
          </div>

          <div className="product-price-row">
            <div>
              <strong className="product-price">{formatPrice(product.price)}</strong>
              {discount > 0 && (
                <span className="product-old-price">
                  {formatPrice(Number(product.price || 0) / (1 - discount / 100))}
                </span>
              )}
            </div>

            <button
              type="button"
              className="product-cart-button"
              onClick={handleCartClick}
              disabled={stock <= 0}
            >
              {stock > 0 ? 'Add' : 'Sold'}
            </button>
          </div>
        </div>
      </Link>
    </article>
  );
}

export default ProductCard;
